package JavaPgm;

public class CheckGivenNumberIsOddOrEven {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        int a = 10;

        if (a % 2 == 0) {

                       System.out.println("Given number is even");

        } else {

                       System.out.println("Given number is odd");

        }
	}

}
